cd scaffold/server && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createHmac } from 'node:crypto';
import { MongoClient } from 'mongodb';

const base = 'http://127.0.0.1:4123';
const secret = 'whsec_pigeon_dev';
const client = new MongoClient('mongodb://localhost:27017/switchboard');
const db = client.db();
const suffix = Date.now().toString(36);
const workspace = 'ws_acme';
const eventId = `it_evt_${suffix}`;
const messageId = `it_msg_${suffix}`;
const clientRef = `it_ref_${suffix}`;

function sign(body, timestamp = Math.floor(Date.now() / 1000)) {
  const digest = createHmac('sha256', secret).update(`${timestamp}.`).update(body).digest('hex');
  return `t=${timestamp},v1=${digest}`;
}
async function post(payload, timestamp = Math.floor(Date.now() / 1000), signature) {
  const body = Buffer.from(JSON.stringify(payload));
  return fetch(`${base}/webhooks/pigeon`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-pigeon-signature': signature ?? sign(body, timestamp),
      ...(payload.id ? { 'x-pigeon-event-id': payload.id } : {}),
    },
    body,
  });
}
async function waitReady() {
  for (let i = 0; i < 30; i++) {
    try { if ((await fetch(`${base}/healthz`)).ok) return; } catch {}
    await new Promise((resolve) => setTimeout(resolve, 300));
  }
  throw new Error('server did not become ready');
}

await client.connect();
try {
  await waitReady();
  const inbound = {
    id: eventId,
    type: 'message.inbound',
    workspace,
    occurred_at: new Date().toISOString(),
    data: { message_id: messageId, from: '+14155550101', text: 'integration check' },
  };
  assert.equal((await post(inbound)).status, 204);
  assert.equal((await post(inbound)).status, 204);
  assert.equal(await db.collection('pigeon_events').countDocuments({ workspace, eventId }), 1);
  assert.equal(await db.collection('inbound_messages').countDocuments({ workspace, messageId }), 1);

  const forged = await post(inbound, undefined, `t=${Math.floor(Date.now() / 1000)},v1=${'0'.repeat(64)}`);
  assert.equal(forged.status, 401);
  assert.equal((await post(inbound, Math.floor(Date.now() / 1000) - 301)).status, 401);

  const unknown = await post({ type: 'future.event', workspace, id: `it_unknown_${suffix}` });
  assert.equal(unknown.status, 204);

  await db.collection('outbound_messages').insertOne({ workspace, clientRef, status: 'queued' });
  const deliveredAt = new Date(Date.now() - 1000).toISOString();
  const delivered = {
    id: `it_status_delivered_${suffix}`, type: 'message.status', workspace,
    occurred_at: deliveredAt,
    data: { message_id: `it_pm_${suffix}`, client_ref: clientRef, status: 'delivered' },
  };
  const sent = {
    id: `it_status_sent_${suffix}`, type: 'message.status', workspace,
    occurred_at: new Date(Date.now() - 2000).toISOString(),
    data: { message_id: `it_pm_${suffix}`, client_ref: clientRef, status: 'sent' },
  };
  assert.equal((await post(delivered)).status, 204);
  assert.equal((await post(sent)).status, 204);
  assert.equal((await db.collection('outbound_messages').findOne({ workspace, clientRef })).status, 'delivered');

  console.log('PASS duplicate webhook: one event and one inbound message persisted');
  console.log('PASS forged and stale signatures: both rejected with 401');
  console.log('PASS unknown event type: acknowledged with 204');
  console.log('PASS late sent status: did not downgrade delivered');
} finally {
  await db.collection('pigeon_events').deleteMany({ workspace, eventId: { $regex: `^it_.*${suffix}` } });
  await db.collection('inbound_messages').deleteMany({ workspace, messageId });
  await db.collection('outbound_messages').deleteMany({ workspace, clientRef });
  await client.close();
}
