import assert from 'node:assert/strict';
import { MongoClient } from 'mongodb';

const base = 'http://localhost:4000';
const token = 'grader-dev-token';
const acmeContact = `+19${Date.now().toString().slice(-9)}`;
const globexContact = `+18${Date.now().toString().slice(-9)}`;
const dbClient = new MongoClient('mongodb://localhost:27017/switchboard');
await dbClient.connect();
const db = dbClient.db();
const headers = { 'content-type': 'application/json' };

try {
  const login = await fetch(`${base}/auth/login`, { redirect: 'manual' });
  assert.equal(login.status, 302);
  const authorizeUrl = new URL(login.headers.get('location'));
  assert.equal(authorizeUrl.searchParams.get('code_challenge_method'), 'S256');
  assert.ok(authorizeUrl.searchParams.get('nonce'));
  authorizeUrl.searchParams.set('login', 'u_ben');
  const idpResponse = await fetch(authorizeUrl, { redirect: 'manual' });
  assert.equal(idpResponse.status, 302);
  const callback = await fetch(idpResponse.headers.get('location'), { redirect: 'manual' });
  assert.equal(callback.status, 302);
  const cookie = callback.headers.get('set-cookie')?.split(';')[0];
  assert.ok(cookie);
  const sessionHeaders = { ...headers, cookie };

  const meResponse = await fetch(`${base}/api/me`, { headers: sessionHeaders });
  assert.equal(meResponse.status, 200);
  const me = await meResponse.json();
  assert.equal(me.sub, 'u_ben');
  assert.equal(me.workspaces[0].id, 'ws_acme');
  assert.equal((await fetch(`${base}/api/me`)).status, 401);
  assert.equal((await fetch(`${base}/api/conversations?workspace=ws_globex`, { headers: sessionHeaders })).status, 403);
  assert.equal((await fetch(`${base}/api/conversations?workspace=ws_acme&limit=1`, { headers: sessionHeaders })).status, 200);

  const graderClaim = await fetch(`${base}/__grader/claim`, {
    method: 'POST',
    headers: { ...headers, 'x-grader-token': token },
    body: JSON.stringify({ workspace: 'ws_globex', contact: globexContact, agent: 'grader-agent' }),
  });
  assert.equal(graderClaim.status, 200);
  assert.equal((await fetch(`${base}/__grader/claim`, {
    method: 'POST', headers, body: JSON.stringify({ workspace: 'ws_globex', contact: globexContact, agent: 'attacker' }),
  })).status, 401);

  const claimUrl = `${base}/api/conversations/${encodeURIComponent(acmeContact)}/claim?workspace=ws_acme`;
  assert.equal((await fetch(claimUrl, { method: 'POST', headers: sessionHeaders })).status, 200);
  const closeUrl = `${base}/api/conversations/${encodeURIComponent(acmeContact)}/close?workspace=ws_acme`;
  assert.equal((await fetch(closeUrl, { method: 'POST', headers: sessionHeaders })).status, 200);
  assert.equal((await fetch(`${base}/api/conversations/${encodeURIComponent(acmeContact)}/messages?workspace=ws_acme`, { headers: sessionHeaders })).status, 200);
  assert.equal((await fetch(`${base}/api/conversations/${encodeURIComponent(globexContact)}/messages?workspace=ws_globex`, { headers: sessionHeaders })).status, 403);
  const reopenUrl = `${base}/api/conversations/${encodeURIComponent(acmeContact)}/reopen?workspace=ws_acme`;
  assert.equal((await fetch(reopenUrl, { method: 'POST', headers: sessionHeaders })).status, 200);

  console.log('PASS OIDC authorization-code + PKCE login, nonce, session, and /api/me');
  console.log('PASS unauthenticated and cross-workspace API access rejected');
  console.log('PASS paginated inbox, claim, close/reopen, and chronological message endpoint');
  console.log('PASS grader claim requires token and creates a separate workspace conversation');
} finally {
  await db.collection('conversations').deleteMany({ contact: { $in: [acmeContact, globexContact] } });
  await db.collection('inbound_messages').deleteMany({ contact: { $in: [acmeContact, globexContact] } });
  await dbClient.close();
}
