cd scaffold/server && node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createHmac } from 'node:crypto';
import { MongoClient } from 'mongodb';

const base = 'http://localhost:4000';
const secret = 'whsec_pigeon_dev';
const suffix = Date.now().toString(36);
const contact = `+19${Date.now().toString().slice(-9)}`;
const eventIds = [`it_in_${suffix}_late`, `it_in_${suffix}_early`];
const messageIds = [`it_msg_${suffix}_late`, `it_msg_${suffix}_early`];
const dbClient = new MongoClient('mongodb://localhost:27017/switchboard');
await dbClient.connect();
const db = dbClient.db();

async function sendEvent(id, messageId, text, occurredAt) {
  const payload = {
    id,
    type: 'message.inbound',
    workspace: 'ws_acme',
    occurred_at: occurredAt.toISOString(),
    data: { message_id: messageId, from: contact, text },
  };
  const body = Buffer.from(JSON.stringify(payload));
  const timestamp = Math.floor(Date.now() / 1000);
  const digest = createHmac('sha256', secret).update(`${timestamp}.`).update(body).digest('hex');
  return fetch(`${base}/webhooks/pigeon`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'x-pigeon-signature': `t=${timestamp},v1=${digest}`,
      'x-pigeon-event-id': id,
    },
    body,
  });
}

try {
  const lateTime = new Date('2026-03-01T12:00:00.000Z');
  const earlyTime = new Date('2026-03-01T11:00:00.000Z');
  assert.equal((await sendEvent(eventIds[0], messageIds[0], 'late event', lateTime)).status, 204);
  assert.equal((await sendEvent(eventIds[0], messageIds[0], 'late event', lateTime)).status, 204);
  assert.equal((await sendEvent(eventIds[1], messageIds[1], 'early event', earlyTime)).status, 204);

  const login = await fetch(`${base}/auth/login`, { redirect: 'manual' });
  const authorize = new URL(login.headers.get('location'));
  authorize.searchParams.set('login', 'u_ben');
  const selected = await fetch(authorize, { redirect: 'manual' });
  const callback = await fetch(selected.headers.get('location'), { redirect: 'manual' });
  const cookie = callback.headers.get('set-cookie')?.split(';')[0];
  assert.ok(cookie);
  const inbox = await fetch(`${base}/api/conversations?workspace=ws_acme&limit=100`, { headers: { cookie } });
  assert.equal(inbox.status, 200);
  const inboxBody = await inbox.json();
  const conversation = inboxBody.conversations.find((entry) => entry.contact === contact);
  assert.ok(conversation);
  assert.equal(new Date(conversation.lastActivityAt).toISOString(), lateTime.toISOString());

  const messages = await fetch(`${base}/api/conversations/${encodeURIComponent(contact)}/messages?workspace=ws_acme`, { headers: { cookie } });
  assert.equal(messages.status, 200);
  const messageBody = await messages.json();
  assert.deepEqual(messageBody.messages.map((entry) => entry.messageId), [messageIds[1], messageIds[0]]);
  assert.equal(await db.collection('inbound_messages').countDocuments({ workspace: 'ws_acme', contact }), 2);

  console.log('PASS signed inbound events created one workspace/contact conversation');
  console.log('PASS duplicate webhook was idempotent and older late arrival did not regress activity');
  console.log('PASS authenticated inbox lists it and messages are oldest-first');
} finally {
  await db.collection('pigeon_events').deleteMany({ eventId: { $in: eventIds } });
  await db.collection('inbound_messages').deleteMany({ workspace: 'ws_acme', contact });
  await db.collection('conversations').deleteMany({ workspace: 'ws_acme', contact });
  await dbClient.close();
}
