     { _id: job._id, leaseOwner },
     {
       $set: {
         nextAttemptAt: new Date(Date.now() + Math.max(0, delayMs)),
         lastError: reason.slice(0, 500),
         updatedAt: new Date(),
       },
       $unset: { leaseOwner: '', leaseUntil: '' },
     },
   );
 }

