 async function storeEventReceipt(
   collection: ReturnType<Awaited<ReturnType<typeof getDb>>['collection']>,
   event: PigeonEvent,
   occurredAt: Date,
 ): Promise<void> {
   const filter = { workspace: event.workspace, eventId: event.id };
   await upsertOnce(collection, filter, {
     ...filter,
     type: event.type,
     occurredAt,
     payload: event,
     receivedAt: new Date(),
   });
