 async function upsertOnce(
   collection: ReturnType<Awaited<ReturnType<typeof getDb>>['collection']>,
   filter: Document,
   document: Document,
 ): Promise<void> {
   try {
     await collection.updateOne(filter, { $setOnInsert: document }, { upsert: true });
   } catch (error) {
